style.css:
@-moz-document domain("infobae.com") {
html, body {
    overflow-x: hidden !important;
  }

  body.nd-body, body {
    margin: 0 !important;
    padding: 0 !important;
    max-width: 100% !important;
    width: 100% !important;
  }

  #fusion-app,
  main[role="main"],
  .layout, .wrapper, .container,
  [class*="content"], [class*="Content"],
  [class*="main"], [class*="Main"],
  [class*="center"], [class*="Center"] {
    max-width: 100% !important;
    width: 100% !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
  }

  /* Eliminar columnas laterales */
  .homepage-centered-left-span.span-rail.span-rail-section,
  .homepage-centered-right-span.span-rail.span-rail-section {
    display: none !important;
    visibility: hidden !important;
    width: 0 !important;
    height: 0 !important;
  }

  /* Forzar cuerpo central a ocupar todo el espacio */
  .homepage-centered-body,
  .homepage-centered-content {
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 auto !important;
  }

  /* Ocultar anuncios, rails y sidebars */
  aside,
  [class*="sidebar"], [id*="sidebar"],
  [class*="rail"], [id*="rail"],
  .ad, .ads, [class*="ad-"], [class*="-ad"],
  [id*="ad-"], [id*="-ad"], [data-ad],
  [aria-label="Publicidad"], [aria-label="Anuncio"] {
    display: none !important;
  }

  article, [class*="article"], .story, .post, .note {
    width: 100% !important;
    max-width: 100% !important;
  }
}
